def lcf_to_edges(lcf):
    """Convert LCF notation to edge list. 
    LCF notation: for each vertex i, connect to (i + lcf[i]) mod n.
    The graph is assumed to be Hamiltonian with the cycle 0-1-2-...-(n-1)-0."""
    n = len(lcf)
    edges = set()
    for i in range(n):
        # edge of the Hamiltonian cycle
        j = (i + 1) % n
        if i < j:
            edges.add((i, j))
        else:
            edges.add((j, i))
        # additional edge from LCF
        j = (i + lcf[i]) % n
        if i < j:
            edges.add((i, j))
        else:
            edges.add((j, i))
    return list(edges)

def girth(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    best = float('inf')
    for start in range(n):
        parent = [-1]*n
        dist = [-1]*n
        dist[start] = 0
        q = [start]
        for u in q:
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    q.append(w)
                elif w != parent[u]:
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best <= 6:
            return best
    return best

