def is_bipartite(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1]*n
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            q = [start]
            for u in q:
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False, None
    return True, color

