def find_odd_cycle(adj, n):
    color = [-1]*n
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            parent = [-1]*n
            q = [start]
            for u in q:
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        parent[v] = u
                        q.append(v)
                    elif color[v] == color[u]:
                        # found odd cycle
                        # reconstruct
                        cycle = []
                        a, b = u, v
                        while a != -1:
                            cycle.append(a)
                            a = parent[a]
                        while b != -1:
                            cycle.append(b)
                            b = parent[b]
                        return cycle
    return None

