# Try to 3-color using backtracking
def can_color(adj, n, max_colors):
    colors = [-1]*n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(max_colors):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    if backtrack(0):
        return colors
    return None

